parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "resumen": {
      "type": "string",
      "description": "Resumen de la noticia en español, 60-100 palabras, tono informativo, cercano y divulgativo"
    },
    "tono": {
      "type": "string",
      "description": "Etiqueta descriptiva del registro aplicado, para trazabilidad interna"
    },
    "prompt_imagen": {
      "type": "string",
      "description": "Prompt en inglés para el modelo de generación de imagen (Nano Banana), 30-60 palabras"
    }
  },
  "required": ["resumen", "tono", "prompt_imagen"]
}

parameters.jsCode:
const response = $input.first().json;
const parts = (response.candidates && response.candidates[0] && response.candidates[0].content && response.candidates[0].content.parts) || [];
const imagePart = parts.find((p) => p.inlineData || p.inline_data);
const inline = imagePart ? (imagePart.inlineData || imagePart.inline_data) : undefined;
if (!inline || !inline.data) {
  throw new Error('Nano Banana no devolvio ninguna imagen en la respuesta: ' + JSON.stringify(response).slice(0, 500));
}
const buffer = Buffer.from(inline.data, 'base64');
const mimeType = inline.mimeType || inline.mime_type || 'image/png';
const binary = await this.helpers.prepareBinaryData(buffer, 'noticia.png', mimeType);
return [{ json: response, binary: { data: binary } }];
